#include <memory>
#include <vector>

// A global container of Widgets
std::vector<std::shared_ptr<class Widget>> processedWidgets;

// Widget must inherit from std::enable_shared_from_this
class Widget : public std::enable_shared_from_this<Widget> {
public:
    void process() {
        // DANGEROUS: This creates a new control block, independent of any
        // shared_ptr that might already own this object.
        // processedWidgets.emplace_back(this); // WRONG!

        // CORRECT: This safely creates a new shared_ptr that shares
        // ownership with any existing shared_ptrs.
        processedWidgets.emplace_back(shared_from_this());
    }
};

void run_example() {
    // Create a Widget managed by a shared_ptr
    auto spw = std::make_shared<Widget>();

    // When process() is called, it can now safely create another shared_ptr to itself
    spw->process();

    // GOTCHA: Calling shared_from_this on an object not owned by shared_ptr
    Widget standaloneWidget;
    // standaloneWidget.process(); // Throws std::bad_weak_ptr
}
